:root{
  --bg:#0b0b0f;
  --surface:#13131a;
  --surface-2:#1a1a24;
  --text:#e9e9f1;
  --muted:#a2a2b3;
  --primary:#7c5cff;
  --primary-2:#5a3df0;
  --accent:#ff6b9d;
  --ring: rgba(124,92,255,.35);
  --border:#242435;
}

@keyframes float{
  0%, 100%{ transform: translateY(0px) rotate(0deg); }
  50%{ transform: translateY(-20px) rotate(3deg); }
}

@keyframes glow{
  0%, 100%{ box-shadow: 0 8px 18px var(--ring), inset 0 1px 0 rgba(255,255,255,.2); }
  50%{ box-shadow: 0 12px 28px rgba(124,92,255,.55), inset 0 1px 0 rgba(255,255,255,.3); }
}

@keyframes shimmer{
  0%{ background-position: -1000px 0; }
  100%{ background-position: 1000px 0; }
}

*{box-sizing:border-box; margin:0; padding:0;}
html,body{height:100%}
body{
  margin:0; font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif;
  background:
    radial-gradient(circle at 20% 50%, rgba(255,107,157,.08), transparent 40%),
    radial-gradient(1200px 600px at 10% -10%, rgba(124,92,255,.15), transparent 50%),
    radial-gradient(1000px 500px at 110% 10%, rgba(124,92,255,.1), transparent 60%),
    var(--bg);
  color:var(--text);
  overflow-x:hidden;
}

/* Layout */
.si-container{ width:92%; max-width:1100px; margin:0 auto; }
.si-main{ padding:28px 0 60px; }
.si-grid{ display:grid; grid-template-columns: 1fr; gap:20px; }
@media(min-width: 980px){
  .si-grid{ grid-template-columns: minmax(0,1fr) 340px; }
  .si-col-wide{ order:1; }
  .si-col-side{ order:2; }
}
.si-col-wide, .si-col-side{ min-width:0; }

/* Navbar */
.si-navbar{ 
  position:sticky; top:0; z-index:20; 
  background: rgba(11,11,15,.85); 
  backdrop-filter: blur(16px) saturate(180%); 
  border-bottom:1px solid var(--border);
  transition: all .3s ease;
}
.si-navbar:hover{ background: rgba(11,11,15,.95); }
.si-nav-inner{ display:flex; align-items:center; justify-content:space-between; gap:16px; padding:14px 0; }
.si-brand{ 
  display:flex; align-items:center; gap:12px; 
  text-decoration:none; color:var(--text); 
  font-weight:800; letter-spacing:.3px;
  transition: transform .3s ease;
}
.si-brand:hover{ transform: scale(1.02); }
.si-badge{ 
  display:grid; place-items:center; 
  width:40px; height:40px; 
  border-radius:14px; 
  background: linear-gradient(135deg, var(--primary), var(--primary-2));
  box-shadow: 0 8px 18px var(--ring), inset 0 1px 0 rgba(255,255,255,.2); 
  font-weight:900;
  animation: glow 3s ease-in-out infinite;
  transition: transform .3s ease;
}
.si-badge:hover{ transform: rotate(10deg) scale(1.05); }
.si-title{ font-size:1.15rem; background: linear-gradient(135deg, var(--text), var(--muted)); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; }
.si-nav-actions{ display:flex; gap:6px; }
.si-nav-actions a{ 
  color:var(--text); text-decoration:none; 
  padding:10px 14px; border-radius:12px;
  transition: all .3s ease;
  border: 1px solid transparent;
}
.si-nav-actions a:hover{ 
  background:var(--surface); 
  border-color:var(--border);
  transform: translateY(-2px);
}

/* Cards */
.si-card{ 
  background: linear-gradient(180deg, rgba(255,255,255,.04), transparent 40%) , var(--surface); 
  border:1px solid var(--border); 
  border-radius:20px; 
  box-shadow: 0 10px 40px rgba(0,0,0,.4), 0 0 1px rgba(124,92,255,.2); 
  overflow:hidden;
  transition: all .4s cubic-bezier(.4,0,.2,1);
  position: relative;
}
.si-card::before{
  content: '';
  position: absolute;
  top: 0; left: -100%;
  width: 100%; height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,.03), transparent);
  transition: left .6s ease;
}
.si-card:hover{
  transform: translateY(-4px);
  box-shadow: 0 20px 50px rgba(0,0,0,.5), 0 0 20px rgba(124,92,255,.15);
  border-color: rgba(124,92,255,.3);
}
.si-card:hover::before{ left: 100%; }
.si-card-header{ 
  padding:18px 20px; 
  border-bottom:1px solid var(--border);
  background: linear-gradient(180deg, rgba(124,92,255,.05), transparent);
}
.si-card-header h2, .si-card-header h3{ 
  margin:0; font-size:1.1rem;
  background: linear-gradient(135deg, var(--text), var(--primary));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}
.si-card-body{ padding:20px; }
.center{ text-align:center; }

/* Buttons */
.si-btn{ 
  display:inline-block; 
  background:linear-gradient(135deg, var(--primary), var(--primary-2)); 
  color:#fff; border:none; 
  border-radius:14px; 
  padding:13px 22px; 
  text-decoration:none; 
  font-weight:600; 
  box-shadow: 0 8px 20px var(--ring);
  cursor:pointer;
  position: relative;
  overflow: hidden;
  transition: all .3s ease;
}
.si-btn::before{
  content: '';
  position: absolute;
  top: 50%; left: 50%;
  width: 0; height: 0;
  border-radius: 50%;
  background: rgba(255,255,255,.2);
  transform: translate(-50%, -50%);
  transition: width .6s ease, height .6s ease;
}
.si-btn:hover{
  transform: translateY(-2px);
  box-shadow: 0 12px 28px rgba(124,92,255,.45);
}
.si-btn:hover::before{
  width: 300px; height: 300px;
}
.si-btn:active{ transform: translateY(0px); }
.si-btn-ghost{ 
  background:transparent; 
  border:1px solid var(--border); 
  color:var(--text); 
  box-shadow:none;
}
.si-btn-ghost:hover{ 
  background:var(--surface-2); 
  border-color:var(--primary);
  box-shadow: 0 4px 12px rgba(124,92,255,.2);
}

/* Forms */
.si-form{ display:flex; flex-direction:column; gap:14px; }
.si-row{ display:grid; grid-template-columns: 1fr; gap:14px; }
@media(min-width:720px){ .si-row{ grid-template-columns: 1fr 1fr; } }
.si-form input, .si-form textarea{
  width:100%; 
  background:var(--surface-2); 
  color:var(--text);
  border:1px solid var(--border); 
  border-radius:14px; 
  padding:13px 16px; 
  outline:none;
  transition: all .3s ease;
  font-family: inherit;
}
.si-form input:focus, .si-form textarea:focus{ 
  border-color:var(--primary); 
  box-shadow:0 0 0 4px var(--ring);
  background: rgba(26,26,36,.8);
  transform: translateY(-1px);
}
.si-form textarea{ min-height:140px; resize:vertical; }

/* Feed grid */
.feed-grid{ display:grid; grid-template-columns: 1fr; gap:16px; }
@media(min-width:620px){ .feed-grid{ grid-template-columns: 1fr 1fr; } }
@media(min-width:1024px){ .feed-grid{ grid-template-columns: 1fr 1fr 1fr; } }
.post{ 
  background:var(--surface-2); 
  border:1px solid var(--border); 
  border-radius:18px; 
  overflow:hidden;
  transition: all .4s cubic-bezier(.4,0,.2,1);
  position: relative;
}
.post::after{
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background: linear-gradient(135deg, rgba(124,92,255,.05), transparent);
  opacity: 0;
  transition: opacity .3s ease;
  pointer-events: none;
}
.post:hover{
  transform: translateY(-6px) scale(1.02);
  border-color: rgba(124,92,255,.4);
  box-shadow: 0 16px 40px rgba(0,0,0,.4), 0 0 20px rgba(124,92,255,.2);
}
.post:hover::after{ opacity: 1; }
.post img, .post video{ 
  display:block; width:100%; height:auto;
  transition: transform .4s ease;
}
.post:hover img, .post:hover video{ transform: scale(1.05); }
.post .meta{ 
  padding:12px 14px; 
  display:flex; align-items:center; 
  justify-content:space-between;
  background: linear-gradient(180deg, transparent, rgba(0,0,0,.1));
}
.post h3{ 
  margin:12px 14px 0; 
  font-size:1.05rem;
  color: var(--text);
}
.post p{ 
  margin:8px 14px 16px; 
  color:var(--muted);
  line-height: 1.5;
}

/* Lists & text */
.si-strong{ font-weight:700; color: var(--text); }
.si-dim{ color:var(--muted); }
.si-list{ list-style:none; padding:0; margin:0; display:grid; gap:10px; }
.si-links{ display:grid; gap:10px; }
.si-links a{ 
  color:var(--text); 
  text-decoration:none; 
  padding:12px 14px; 
  border-radius:12px; 
  border:1px solid var(--border);
  transition: all .3s cubic-bezier(.4,0,.2,1);
  position: relative;
  overflow: hidden;
}
.si-links a::before{
  content: '';
  position: absolute;
  left: 0; top: 0;
  height: 100%; width: 3px;
  background: linear-gradient(180deg, var(--primary), var(--accent));
  transform: translateX(-3px);
  transition: transform .3s ease;
}
.si-links a:hover{ 
  background:var(--surface-2); 
  border-color: var(--primary);
  transform: translateX(4px);
  box-shadow: 0 4px 12px rgba(124,92,255,.15);
}
.si-links a:hover::before{
  transform: translateX(0);
}

/* Footer */
.si-footer{ 
  border-top:1px solid var(--border); 
  padding:24px 0; 
  background:linear-gradient(180deg, transparent, rgba(124,92,255,.03));
  margin-top: 40px;
}

/* Scrollbar */
::-webkit-scrollbar{ width: 10px; }
::-webkit-scrollbar-track{ background: var(--bg); }
::-webkit-scrollbar-thumb{ 
  background: linear-gradient(180deg, var(--primary), var(--primary-2)); 
  border-radius: 10px;
  border: 2px solid var(--bg);
}
::-webkit-scrollbar-thumb:hover{ background: var(--primary); }

/* Selection */
::selection{
  background: rgba(124,92,255,.3);
  color: var(--text);
}
